    category: 'ഗ്രന്ഥം എങ്ങനെ ചുറ്റപ്പെട്ടിരിക്കുന്നു',
    summary: `ആറ് അംഗങ്ങൾക്ക് അപ്പുറം ഈ പതിപ്പ് പതിനൊന്ന് അനുബന്ധങ്ങൾ ചേർക്കുന്നു (പുറം 760-794). പീഠരഹസ്യം (മത്സ്യപുരാണം 13) ആദ്യം എല്ലാ പരിമിതിയും നിരാകരിക്കുന്നു — "എന്നെയല്ലാതെ ഒന്നുമില്ല" — പിന്നെ 108 പീഠങ്ങൾ നൽകുന്നു, പുറംതീർത്ഥങ്ങളും അകത്തെ സ്ഥാനങ്ങളും (ചിത്തബ്രഹ്മകല) ഒരേ മാലയിൽ. മഹാവിദ്യാരഹസ്യം (മഹാഭാഗവതം 8) ദക്ഷയജ്ഞതർക്കം അരങ്ങേറ്റി പത്ത് വിദ്യകളെ പത്ത് ദിക്കുകളായി വെളിപ്പെടുത്തുന്നു — കാളീ മുൻപിൽ, താരാ മുകളിൽ, ഛിന്നമസ്താ വശത്ത്, ഭുവനേശ്വരീ ഇടത്ത്, ബഗളാ പിന്നിൽ, ധൂമാവതീ അഗ്നിയിൽ, സുന്ദരീ നൈരൃതിയിൽ, മാതംഗീ വായുവിൽ, ഷോഡശീ ഈശാനത്തിൽ, ഭൈരവീ നടുവിൽ — എല്ലാം ഗോപനീയം, ശിവൻ മാത്രം പറയണം. കാളികാമാഹാത്മ്യം (സ്കന്ദപുരാണം മാനസഖണ്ഡം 97) ഒരു കുന്നിനെ (ശൈലം, പിത്തോറഗഡ്) ഉറപ്പിക്കുന്നു — പഴയ വിജയങ്ങൾ അവളെ സ്ഥിരവാസിയാക്കുന്നു. പിന്നെ സങ്കടപാരായണം: 15 ശ്ലോക ലഘുസപ്തശതി (മുഴുവൻ യുദ്ധം ഒറ്റ ഇരിപ്പിൽ), 13 ശ്ലോക ആപദുദ്ധാരം (ഒരേ ആവർത്തനം — "ത്രാഹി ദുർഗ്ഗേ"), 17 ഏറ്റുപറച്ചിൽ കാളീസ്തോത്രം (ജീവചരിത്രം ക്ഷമാപണം), യാമളശാന്തി (എല്ലാവരെയും അനുഗ്രഹിക്കൂ, ദൂഷകരെ അതിർത്തിക്ക് പുറത്ത്), പൗരാണികാഭിഷേകങ്ങൾ (പ്രപഞ്ചത്താൽ അഭിഷേകം), 1000 നാമ പരാദേവീമാല (അസ്ഥികൂടം കൃത്യം, ശരീരം സൂചിക), 700 ഘടകപാരായണത്തെ ഒരേ ലക്ഷ്യത്തിലേക്ക് പൊതിയുന്ന 30 ഉദ്ദേശ്യ സിദ്ധസമ്പുടപ്പട്ടിക.`,
    relatedVerseIds: ['dm-pitha-rahasya', 'dm-mahavidya-rahasya', 'dm-kalika-mahatmya', 'dm-laghu-saptashati', 'dm-apaduddhara', 'dm-kali-stotra', 'dm-shanti-stotra', 'dm-pauranika-shanti', 'dm-para-devi-sukta', 'dm-siddha-samputa'],
